44:         ResourceManager_() : m_shutdown(false) {}
45:         RESOURCE_TYPE Acquire()
46:         {
47:             std::unique_lock<std::mutex> locker(m_queueLock);
48:             while(!m_shutdown.load() && m_resources.size() == 0)
49:             {
50:                 m_semaphore.wait(locker, [&](){ return m_shutdown.load() || m_resources.size() > 0; });                    
51:             }
52:     
53:             assert(!m_shutdown.load());
54:     
55:             RESOURCE_TYPE resource = m_resources.back();
56:             m_resources.pop_back();
57:     
58:             return resource;
59:         }
60:     
61:         bool HasResourcesAvailable()
62:         {
63:             std::lock_guard<std::mutex> locker(m_queueLock);
64:             return m_resources.size() > 0 && !m_shutdown.load();
65:         }
66:     
67:         void Release(RESOURCE_TYPE resource)
68:         {
69:             std::unique_lock<std::mutex> locker(m_queueLock);
70:             m_resources.push_back(resource);
71:             locker.unlock();
72:             m_semaphore.notify_one();
73:         }
