80:         std::vector<RESOURCE_TYPE> ShutdownAndWait(size_t resourceCount)
81:         {
82:             std::vector<RESOURCE_TYPE> resources;
83:             std::unique_lock<std::mutex> locker(m_queueLock);
84:             m_shutdown = true;
85:             while (m_resources.size() < resourceCount)
86:             {
87:                 m_semaphore.wait(locker, [&]() { return m_resources.size() == resourceCount; });
88:             }
89:             resources = m_resources;
90:             m_resources.clear();
91:             return resources;
92:         }
