151:         bool growPool()
152:         {
153:             std::lock_guard<std::mutex> locker(containerLock_);
154:             if (poolSize_ < maxPoolSize_) {
155:                 unsigned multiplier = poolSize_ > 0 ? poolSize_ : 1;
156:                 unsigned amountToAdd = (std::min)(multiplier * 2, maxPoolSize_ - poolSize_);
157:         
158:                 unsigned actuallyAdded = 0;
159:                 for (unsigned i = 0; i < amountToAdd; ++i) {
160:                     CURL* curlHandle = curl_easy_init();
161:                     if (curlHandle) {
162:                         setDefaultOptions(curlHandle);
163:                         handleContainer_.Release(curlHandle);
164:                         ++actuallyAdded;
