200:     struct TransferState {
201:         CurlHttpClient *owner;
202:         CURL * curl;
203:         HttpRequest  *request;
204:         HttpResponse *response;
205:         int64_t transferred;
206:         int64_t total;
207:         bool firstRecvData;
208:         std::iostream::pos_type recvBodyPos;
209:         TransferProgressHandler progress;
210:         void *userData;
211:         bool enableCrc64;
212:         uint64_t sendCrc64Value;
213:         uint64_t recvCrc64Value;
214:         int sendSpeed;
215:         int recvSpeed;
216:     };
