218:     static size_t sendBody(char *ptr, size_t size, size_t nmemb, void *userdata)
219:     {
220:         TransferState *state = static_cast<TransferState*>(userdata);
221: 
222:         if (state == nullptr || 
223:             state->request == nullptr) {
224:             return 0;
225:         }
226:         
227:         std::shared_ptr<std::iostream> &content = state->request->Body();
228:         const size_t wanted = size * nmemb;
229:         size_t got = 0;
230:         if (content != nullptr && wanted > 0) {
231:             size_t read = wanted;
232:             if (state->total > 0) {
233:                 int64_t remains = state->total - state->transferred;
234:                 if (remains < static_cast<int64_t>(wanted)) {
235:                     read = static_cast<size_t>(remains);
236:                 }
237:             }
238:             content->read(ptr, read);
239:             got = static_cast<size_t>(content->gcount());
240:         }
241: 
242:         state->transferred += got;
243:         if (state->progress) {
244:             state->progress(got, state->transferred, state->total, state->userData);
245:         }
246: 
247:         if (state->enableCrc64) {
248:             state->sendCrc64Value = CRC64::CalcCRC(state->sendCrc64Value, (void *)ptr, got);
249:         }
250: 
251:         return got;
252:     }
253: 
254:     static size_t recvBody(char *ptr, size_t size, size_t nmemb, void *userdata)
255:     {
256:         TransferState *state = static_cast<TransferState*>(userdata);
257:         const size_t wanted = size * nmemb;
258: 
259:         if (state == nullptr ||
260:             state->response == nullptr || 
261:             wanted == 0) {
262:             return -1;
263:         }
264: 
265:         if (state->firstRecvData) {
266:             long response_code = 0;
267:             curl_easy_getinfo(state->curl, CURLINFO_RESPONSE_CODE, &response_code);
268:             if (response_code / 100 == 2) {
269:                 state->response->addBody(state->request->ResponseStreamFactory()());
270:                 if (state->response->Body() != nullptr) {
271:                     state->recvBodyPos = state->response->Body()->tellp();
272:                 }
273:                 OSS_LOG(LogLevel::LogDebug, TAG, "request(%p) setResponseBody, recvBodyPos:%lld",
274:                     state->request, state->recvBodyPos);
275:             }
276:             else {
277:                 state->response->addBody(std::make_shared<std::stringstream>());
278:             }
279:             state->firstRecvData = false;
280:         }
281: 
282:         std::shared_ptr<std::iostream> &content = state->response->Body();
283:         if (content == nullptr || content->fail()) {
284:             return -2;
285:         }
286: 
287:         content->write(ptr, static_cast<std::streamsize>(wanted));
288:         if (content->bad()) {
289:             return -3;
290:         }
291: 
292:         state->transferred += wanted;
293:         if (state->progress) {
294:             state->progress(wanted, state->transferred, state->total, state->userData);
295:         }
296: 
297:         if (state->enableCrc64) {
298:             state->recvCrc64Value = CRC64::CalcCRC(state->recvCrc64Value, (void *)ptr, wanted);
299:         }
300: 
301:         return wanted;
302:     }
