304:     static size_t recvHeaders(char *buffer, size_t size, size_t nitems, void *userdata)
305:     {
306:         TransferState *state = static_cast<TransferState*>(userdata);
307:         const size_t length = nitems * size;
308: 
309:         std::string line(buffer);
310:         auto pos = line.find(':');
311:         if (pos != line.npos)
312:         {
313:             size_t posEnd = line.rfind('\r');
314:             if (posEnd != line.npos) {
315:                 posEnd = posEnd - pos - 2;
316:             }
317:             std::string name  = line.substr(0, pos);
318:             std::string value = line.substr(pos + 2, posEnd);
319:             state->response->setHeader(name, value);
320:         }
321: 
322:         if (length == 2 && (buffer[0] == 0x0D) && (buffer[1] == 0x0A)) {
323:             if (state->response->hasHeader(Http::CONTENT_LENGTH)) {
324:                 double dval;
325:                 curl_easy_getinfo(state->curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD, &dval);
326:                 state->total = (int64_t)dval;
327:             }
328:         }
329:         return length;
330:     }
